&lt;h2 id=&#34;latex-数学公式&#34;&gt;&lt;a class=&#34;markdownIt-Anchor&#34; href=&#34;#latex-数学公式&#34;&gt;#&lt;/a&gt; LaTeX 数学公式&lt;/h2&gt;
&lt;p&gt;行内公式：&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;E&lt;/mi&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mi&gt;m&lt;/mi&gt;&lt;msup&gt;&lt;mi&gt;c&lt;/mi&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;/msup&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;E = mc^2&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8141079999999999em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;strut bottom&#34; style=&#34;height:0.8141079999999999em;vertical-align:0em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;base textstyle uncramped&#34;&gt;&lt;span class=&#34;mord mathit&#34; style=&#34;margin-right:0.05764em;&#34;&gt;E&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mord mathit&#34;&gt;m&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathit&#34;&gt;c&lt;/span&gt;&lt;span class=&#34;vlist&#34;&gt;&lt;span style=&#34;top:-0.363em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;fontsize-ensurer reset-size5 size5&#34;&gt;&lt;span style=&#34;font-size:0em;&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;reset-textstyle scriptstyle uncramped&#34;&gt;&lt;span class=&#34;mord mathrm&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;baseline-fix&#34;&gt;&lt;span class=&#34;fontsize-ensurer reset-size5 size5&#34;&gt;&lt;span style=&#34;font-size:0em;&#34;&gt;​&lt;/span&gt;&lt;/span&gt;​&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;，以及 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;s&lt;/mi&gt;&lt;mi&gt;u&lt;/mi&gt;&lt;msubsup&gt;&lt;mi&gt;m&lt;/mi&gt;&lt;mrow&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/mrow&gt;&lt;mrow&gt;&lt;mi&gt;n&lt;/mi&gt;&lt;/mrow&gt;&lt;/msubsup&gt;&lt;mi&gt;i&lt;/mi&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mfrac&gt;&lt;mrow&gt;&lt;mi&gt;n&lt;/mi&gt;&lt;mo&gt;(&lt;/mo&gt;&lt;mi&gt;n&lt;/mi&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;mo&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;mrow&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;/mrow&gt;&lt;/mfrac&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;sum_{i=1}^{n} i = \frac{n(n+1)}{2}&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.01em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;strut bottom&#34; style=&#34;height:1.355em;vertical-align:-0.345em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;base textstyle uncramped&#34;&gt;&lt;span class=&#34;mord mathit&#34;&gt;s&lt;/span&gt;&lt;span class=&#34;mord mathit&#34;&gt;u&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathit&#34;&gt;m&lt;/span&gt;&lt;span class=&#34;vlist&#34;&gt;&lt;span style=&#34;top:0.258664em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;fontsize-ensurer reset-size5 size5&#34;&gt;&lt;span style=&#34;font-size:0em;&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;reset-textstyle scriptstyle cramped&#34;&gt;&lt;span class=&#34;mord scriptstyle cramped&#34;&gt;&lt;span class=&#34;mord mathit&#34;&gt;i&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mord mathrm&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-0.363em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;fontsize-ensurer reset-size5 size5&#34;&gt;&lt;span style=&#34;font-size:0em;&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;reset-textstyle scriptstyle uncramped&#34;&gt;&lt;span class=&#34;mord scriptstyle uncramped&#34;&gt;&lt;span class=&#34;mord mathit&#34;&gt;n&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;baseline-fix&#34;&gt;&lt;span class=&#34;fontsize-ensurer reset-size5 size5&#34;&gt;&lt;span style=&#34;font-size:0em;&#34;&gt;​&lt;/span&gt;&lt;/span&gt;​&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord mathit&#34;&gt;i&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mord reset-textstyle textstyle uncramped&#34;&gt;&lt;span class=&#34;sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mfrac&#34;&gt;&lt;span class=&#34;vlist&#34;&gt;&lt;span style=&#34;top:0.345em;&#34;&gt;&lt;span class=&#34;fontsize-ensurer reset-size5 size5&#34;&gt;&lt;span style=&#34;font-size:0em;&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;reset-textstyle scriptstyle cramped&#34;&gt;&lt;span class=&#34;mord scriptstyle cramped&#34;&gt;&lt;span class=&#34;mord mathrm&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-0.22999999999999998em;&#34;&gt;&lt;span class=&#34;fontsize-ensurer reset-size5 size5&#34;&gt;&lt;span style=&#34;font-size:0em;&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;reset-textstyle textstyle uncramped frac-line&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-0.485em;&#34;&gt;&lt;span class=&#34;fontsize-ensurer reset-size5 size5&#34;&gt;&lt;span style=&#34;font-size:0em;&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;reset-textstyle scriptstyle uncramped&#34;&gt;&lt;span class=&#34;mord scriptstyle uncramped&#34;&gt;&lt;span class=&#34;mord mathit&#34;&gt;n&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathit&#34;&gt;n&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mord mathrm&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;baseline-fix&#34;&gt;&lt;span class=&#34;fontsize-ensurer reset-size5 size5&#34;&gt;&lt;span style=&#34;font-size:0em;&#34;&gt;​&lt;/span&gt;&lt;/span&gt;​&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;。&lt;/p&gt;
&lt;p&gt;块级公式：&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mtable&gt;&lt;mtr&gt;&lt;mtd&gt;&lt;mrow&gt;&lt;mi&gt;f&lt;/mi&gt;&lt;mo&gt;(&lt;/mo&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mo&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;/mtd&gt;&lt;mtd&gt;&lt;mrow&gt;&lt;mrow&gt;&lt;/mrow&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mfrac&gt;&lt;mrow&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/mrow&gt;&lt;mrow&gt;&lt;msqrt&gt;&lt;mrow&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;mi&gt;π&lt;/mi&gt;&lt;msup&gt;&lt;mi&gt;σ&lt;/mi&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;/msup&gt;&lt;/mrow&gt;&lt;/msqrt&gt;&lt;/mrow&gt;&lt;/mfrac&gt;&lt;mi&gt;exp&lt;/mi&gt;&lt;mrow&gt;&lt;mo fence=&#34;true&#34;&gt;(&lt;/mo&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mfrac&gt;&lt;mrow&gt;&lt;mo&gt;(&lt;/mo&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mi&gt;μ&lt;/mi&gt;&lt;msup&gt;&lt;mo&gt;)&lt;/mo&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;/msup&gt;&lt;/mrow&gt;&lt;mrow&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;msup&gt;&lt;mi&gt;σ&lt;/mi&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;/msup&gt;&lt;/mrow&gt;&lt;/mfrac&gt;&lt;mo fence=&#34;true&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;/mrow&gt;&lt;/mtd&gt;&lt;/mtr&gt;&lt;mtr&gt;&lt;mtd&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∇&lt;/mi&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;/msub&gt;&lt;mi&gt;J&lt;/mi&gt;&lt;mo&gt;(&lt;/mo&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;mo&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;/mtd&gt;&lt;mtd&gt;&lt;mrow&gt;&lt;mrow&gt;&lt;/mrow&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;msub&gt;&lt;mrow&gt;&lt;mi mathvariant=&#34;double-struck&#34;&gt;E&lt;/mi&gt;&lt;/mrow&gt;&lt;mrow&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mo&gt;∼&lt;/mo&gt;&lt;mi&gt;p&lt;/mi&gt;&lt;mo&gt;(&lt;/mo&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mo&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;/msub&gt;&lt;mrow&gt;&lt;mo fence=&#34;true&#34;&gt;[&lt;/mo&gt;&lt;msub&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∇&lt;/mi&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;/msub&gt;&lt;mi&gt;log&lt;/mi&gt;&lt;msub&gt;&lt;mi&gt;p&lt;/mi&gt;&lt;mi&gt;θ&lt;/mi&gt;&lt;/msub&gt;&lt;mo&gt;(&lt;/mo&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mo&gt;)&lt;/mo&gt;&lt;mo fence=&#34;true&#34;&gt;]&lt;/mo&gt;&lt;/mrow&gt;&lt;/mrow&gt;&lt;/mtd&gt;&lt;/mtr&gt;&lt;/mtable&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\begin{aligned}
f(x) &amp;amp;= \frac{1}{\sqrt{2\pi\sigma^2}}
       \exp\left(-\frac{(x-\mu)^2}{2\sigma^2}\right) \\
\nabla_\theta J(\theta) &amp;amp;= \mathbb{E}_{x \sim p(x)}
  \left[\nabla_\theta \log p_\theta(x)\right]
\end{aligned}
